function minOperations(nums) {
  // Trial division: the largest proper divisor is x over its smallest divisor above 1 (1 for a prime).
  const largestProperDivisor = (x) => {
    for (let d = 2; d * d <= x; d++) if (x % d === 0) return x / d;
    return 1;
  };
  // Every value an element reaches with up to three operations, with the fewest operations for each.
  const reachable = (x) => {
    const out = new Map([[x, 0]]);
    for (let ops = 1; ops <= 3 && x > 1; ops++) {
      x = x / largestProperDivisor(x);
      if (!out.has(x)) out.set(x, ops);
    }
    return out;
  };
  // Forward DP: best maps the last element's value to the fewest operations keeping the prefix non-decreasing.
  let best = new Map([[0, 0]]);
  for (const x of nums) {
    const next = new Map();
    for (const [value, ops] of reachable(x))
      for (const [last, cost] of best)
        if (last <= value && (!next.has(value) || next.get(value) > cost + ops)) next.set(value, cost + ops);
    best = next;
  }
  return best.size ? Math.min(...best.values()) : -1;
}

