function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const isPrime = (x) => { if (x < 2) return false; for (let d = 2; d * d <= x; d++) if (x % d === 0) return false; return true; };
  const primes = [];
  for (let x = 2; x <= (large ? 997 : 47); x++) if (isPrime(x)) primes.push(x);
  // Some small inputs are fully random: often impossible, sometimes already sorted.
  if (!large && rand() < 0.3) return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 30))];
  // A non-decreasing plan of primes and other values; some primes p are then hidden in p * q
  // (q a prime >= p), whose smallest prime factor is p, so one operation brings p back.
  const plan = Array.from({ length: n }, () => rand() < 0.65 ? pick(primes) : 1 + Math.floor(rand() * (large ? 1000 : 50)));
  plan.sort((a, b) => a - b);
  const hide = large ? 0.6 : 0.65;
  const nums = plan.map(p => isPrime(p) && rand() < hide ? p * pick(primes.filter(q => q >= p && p * q <= 1000000)) : p);
  // Sometimes raise one value so that the order may break beyond repair.
  if (n > 1 && rand() < (large ? 0.3 : 0.25)) {
    const i = Math.floor(rand() * (n - 1));
    nums[i] = rand() < 0.5 ? pick([999983, 999979, 1000000]) : nums[i] + 1 + Math.floor(rand() * 50);
  }
  return [nums];
}
